    interactionTags: listFromText(prop(json, ['互動記錄標籤'])),
    activityRecord: prop(json, ['活動紀錄']),
    activityRecord2: prop(json, ['活動紀錄2', '活動報名模板庫']),
    caseRecord: prop(json, ['案件記錄']),
    legalRecord: prop(json, ['法扶紀錄']),
    note: prop(json, ['備註']),
    address: prop(json, ['戶籍地址']),
    submittedAt: prop(json, ['提交時間']) || json.created_time || '',
    createdAt: prop(json, ['建立時間']) || json.created_time || '',
    lastEditedAt: prop(json, ['上次編輯時間']) || json.last_edited_time || ''
  };
}).filter((item) => item.lineId);
return [{ json: { ok: true, data } }];

